BEGIN TRANSACTION;
CREATE TABLE "alerts" ("id", "assetId", "alertType", "severity", "description", "date", "status", "referenceId");
CREATE TABLE "assets" ("id", "name", "instrumentTypeId", "serialNumber", "manufacturer", "location", "calibrationPlanId", "calibrationPlanName", "referenceValue", "lastCalibration", "interval", "dueDate", "supplierId", "status", "createdAt");
CREATE TABLE "audit_records" ("id", "activity", "description", "performedBy", "date", "referenceId", "entityType", "previousState", "newState");
CREATE TABLE "calibration_events" ("id", "assetId", "name", "calibrationPlanId", "date", "measured", "reference", "tolerance", "error", "result", "engineer", "calibrationType", "workOrderId", "nextDueDate", "createdAt");
CREATE TABLE "calibration_plans" ("id", "name", "instrumentTypeId", "interval", "tolerance", "toleranceUnit", "effectiveFrom", "effectiveTo", "status");
CREATE TABLE "certificates" ("id", "calibrationId", "assetId", "instrumentName", "issueDate", "expiryDate", "status", "issuedBy", "documentReference");
CREATE TABLE "emergency_extensions" ("extensionId", "assetId", "approvedBy", "approvalDate", "effectiveFrom", "effectiveTo", "justification", "status");
CREATE TABLE "instrument_types" ("id", "name", "description", "measurementUnit", "category", "status", "createdAt");
CREATE TABLE "production_usage" ("id", "assetId", "instrument", "batchId", "usageDate", "operator", "productionLine", "status", "issueType", "exceptionId", "createdAt");
CREATE TABLE "suppliers" ("supplierId", "supplierName", "supplierCode", "country", "contactEmail", "status", "createdAt");
CREATE TABLE "work_orders" ("id", "assetId", "calibrationId", "instrumentName", "createdDate", "status", "impactAssessment", "sourceWorkOrderId", "downtimeStart", "downtimeEnd", "downtimeHours", "correctiveAction", "technician", "verificationStatus", "verificationDate", "verificationCalibrationId");
COMMIT;
